  await expect(page.locator('details input#deal-name')).toHaveCount(1);
  await name.fill('  Café 🎴  ');
  expect(await readSnapshot(page)).toMatchObject({ version: 2, name: '  Café 🎴  ' });
  await name.fill('🎴'.repeat(20));
  await name.press('End');
