  await loadTimedBoard(page, gameURL);
  await pasteSnapshot(page, NAMED_PROGRESS);
  const before = await readSnapshot(page);
  const preferences = await page.evaluate((key) => localStorage.getItem(key), PREFERENCES_KEY);
  for (const fields of [
