  assert.equal(decodeSnapshot(JSON.stringify(missing)), null);
  assert.equal(moves, 2);
  assert.equal(
    decodeSnapshot(JSON.stringify({ ...UNNAMED, selection: { ...UNNAMED.selection, extra: true } })),
    null,
  );
  const { remainingMs, ...selection } = UNNAMED.selection;
  assert.equal(decodeSnapshot(JSON.stringify({ ...UNNAMED, selection })), null);
  assert.equal(remainingMs, 300);
});

