      const restored = decodeSnapshot(JSON.stringify(reordered));
      assert.ok(restored, `accept first key ${entries[offset]?.[0]}`);
      assert.equal(restored.name, fixture.version === 2 ? '  Café  ' : '');
      assert.deepEqual(restored.matched, [11, 0]);
